// Cloudflare Worker API for Instakross.
// Required bindings: DB (D1), BUCKET (R2).
// Required secrets: ADMIN_EMAIL, MAIL_TO, MAIL_FROM, RESEND_API_KEY.
const json=(data,status=200)=>new Response(JSON.stringify(data),{status,headers:{'content-type':'application/json; charset=utf-8','access-control-allow-origin':'*','access-control-allow-headers':'content-type'}});
const userFromRequest=request=>request.headers.get('oai-authenticated-user-email')||'';
async function requireAdmin(request,env){const email=userFromRequest(request);if(!email||email.toLowerCase()!==env.ADMIN_EMAIL.toLowerCase())return null;return email}
async function sendOrderEmail(order,env){if(!env.RESEND_API_KEY)return;await fetch('https://api.resend.com/emails',{method:'POST',headers:{authorization:`Bearer ${env.RESEND_API_KEY}`,'content-type':'application/json'},body:JSON.stringify({from:env.MAIL_FROM,to:[env.MAIL_TO],subject:`Новый заказ ${order.id} — Instakross`,html:`<h2>Новый заказ ${order.id}</h2><p>Клиент: ${order.customer_name}</p><p>Телефон: ${order.customer_phone}</p><p>Адрес: ${order.delivery_address}</p><p>Сумма: ${(order.total_cents/100).toLocaleString('ru-RU')} ₽</p>`})})}
export default {async fetch(request,env){const url=new URL(request.url);const path=url.pathname;try{if(request.method==='OPTIONS')return new Response(null,{headers:{'access-control-allow-origin':'*','access-control-allow-methods':'GET,POST,PUT,DELETE','access-control-allow-headers':'content-type'}});if(path==='/api/health')return json({ok:true,service:'instakross'});if(path==='/api/products'&&request.method==='GET'){const {results}=await env.DB.prepare('SELECT * FROM products WHERE published=1 ORDER BY created_at DESC').all();return json(results)}if(path==='/api/orders'&&request.method==='POST'){const body=await request.json();if(!body.customer_name||!body.customer_phone||!body.delivery_address||!Array.isArray(body.items)||!body.items.length)return json({error:'Заполните обязательные поля'},400);const id='IK-'+crypto.randomUUID().slice(0,8).toUpperCase();const total_cents=body.items.reduce((sum,item)=>sum+Number(item.price_cents||0)*Number(item.quantity||1),0);const order={id,customer_name:body.customer_name,customer_email:body.customer_email||'',customer_phone:body.customer_phone,delivery_address:body.delivery_address,items_json:JSON.stringify(body.items),total_cents,status:'new'};await env.DB.prepare('INSERT INTO orders (id,customer_name,customer_email,customer_phone,delivery_address,items_json,total_cents,status) VALUES (?,?,?,?,?,?,?,?)').bind(order.id,order.customer_name,order.customer_email,order.customer_phone,order.delivery_address,order.items_json,order.total_cents,order.status).run();await sendOrderEmail(order,env);return json({id,status:'new'},201)}if(path==='/api/admin/products'&&request.method==='GET'){if(!await requireAdmin(request,env))return json({error:'Unauthorized'},401);const {results}=await env.DB.prepare('SELECT * FROM products ORDER BY created_at DESC').all();return json(results)}if(path==='/api/admin/orders'&&request.method==='GET'){if(!await requireAdmin(request,env))return json({error:'Unauthorized'},401);const {results}=await env.DB.prepare('SELECT * FROM orders ORDER BY created_at DESC').all();return json(results)}if(path==='/api/admin/products'&&request.method==='POST'){if(!await requireAdmin(request,env))return json({error:'Unauthorized'},401);const body=await request.json();const id=crypto.randomUUID();await env.DB.prepare('INSERT INTO products (id,name,slug,category_id,description,price_cents,old_price_cents,color,sizes_json,stock,image_key,published) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)').bind(id,body.name,body.slug,body.category_id,body.description||'',Number(body.price_cents),body.old_price_cents?Number(body.old_price_cents):null,body.color||'#77818a',JSON.stringify(body.sizes||[]),Number(body.stock||0),body.image_key||null,body.published===false?0:1).run();return json({id},201)}if(path.startsWith('/api/admin/uploads/')&&request.method==='PUT'){if(!await requireAdmin(request,env))return json({error:'Unauthorized'},401);const key=path.replace('/api/admin/uploads/','');await env.BUCKET.put(key,request.body,{httpMetadata:{contentType:request.headers.get('content-type')||'application/octet-stream'}});return json({key},201)}return json({error:'Not found'},404)}catch(error){return json({error:error.message||'Server error'},500)}}};
